    internal static class JsonReferenceHelper
    {
        public static JsonNode? ReplaceReferences(JsonNode? node, ReferenceTarget target, ReferenceContext context, IReferenceValueResolver resolver)
        {
            if (node is JsonValue v && v.TryGetValue<string>(out var s))
            {
                return JsonValue.Create(resolver.Resolve(s, target, context)?.ToString() ?? string.Empty);
            }
            if (node is JsonObject obj)
            {
                var clone = new JsonObject();
                foreach (var kv in obj)
                {
                    clone[kv.Key] = kv.Value == null ? null : ReplaceReferences(kv.Value, target, context, resolver);
                }
                return clone;
            }
            if (node is JsonArray arr)
            {
                var clone = new JsonArray();
                foreach (var item in arr)
                {
                    clone.Add(item == null ? null : ReplaceReferences(item, target, context, resolver));
                }
                return clone;
            }
            return node;
        }
    }

    public class JsonContentHandler : ISerializedContentHandler
    {
        private readonly string? _jsonPath;
        public JsonContentHandler(string? jsonPath = null) => _jsonPath = jsonPath;
        public JsonContentHandler() : this(null) { }
        public string Process(string content, ReferenceTarget target, ReferenceContext context, IReferenceValueResolver resolver)
        {
            if (string.IsNullOrEmpty(content)) return content;

            var doc = JsonNode.Parse(content);
            if (doc == null) return content;

            var targetNode = string.IsNullOrEmpty(_jsonPath) ? doc : JsonPathHelper.ResolveJsonPath(doc, _jsonPath);
            if (targetNode == null)
                throw new InvalidOperationException($"JSON path '{_jsonPath}' not found in content. Content: {content.Substring(0, Math.Min(200, content.Length))}...");

            var newToken = JsonReferenceHelper.ReplaceReferences(targetNode, target, context, resolver);

            if (!string.IsNullOrEmpty(_jsonPath) && targetNode != doc)
            {
                JsonPathHelper.SetJsonPath(doc, _jsonPath, newToken);
                return doc.ToJsonString();
            }
            return newToken?.ToJsonString() ?? string.Empty;
        }
    }


